import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(depth=True);c=o.meta['cameras']['egocentric_mirrored_camera'];E=np.array(c['extrinsic_cv']);K=np.array(c['intrinsic_cv']);R=E[:,:3];t=E[:,3];
for uv in [(176,183),(175,180),(177,183),(175,185),(170,180),(180,180)]:
 u,v=uv; ray=np.linalg.solve(R,np.array([(u-K[0,2])/K[0,0],(v-K[1,2])/K[1,1],1.])); owr=-np.linalg.solve(R,t); # camera origin world
 for z in [.01,.02,.03,.04,.05]:
  s=(z-owr[2])/ray[2];P=owr+s*ray
  if z in [.01,.02,.03,.04,.05]: print(uv,z,np.round(P,4))
 print()
